package main
import (
"github.com/gin-gonic/gin"
"net/http"
)
func main() {
r := gin.New()
r.Use(gin.Recovery())
r.GET("/start", func(c *gin.Context) { c.Redirect(http.StatusFound, "/hello") })
r.GET("/hello", func(c *gin.Context) { c.String(http.StatusOK, "Welcome") })
r.Run("127.0.0.1:3000")
}
